import PDFDocument from "pdfkit";
import { NextApiRequest, NextApiResponse } from "next";

export const config = {
  api: {
    bodyParser: { sizeLimit: "2mb" },
  },
};

const themeColors = [
  "#e0e0e0", // gris très clair
  "#bfc4c5", // gris clair
  "#444444", // gris foncé
  "#1a7f6b", // vert
  "#000000", // noir
];

function getInfluenceColor(val: number, max: number) {
  if (max === 0) return themeColors[0];
  const ratio = val / max;
  if (ratio > 0.8) return themeColors[4];
  if (ratio > 0.6) return themeColors[3];
  if (ratio > 0.3) return themeColors[2];
  if (ratio > 0) return themeColors[1];
  return themeColors[0];
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "POST") {
    res.status(405).end("Method Not Allowed");
    return;
  }

  const {
    label,
    companyName,
    period,
    data,
    influenceHistory = [],
    chartImage = "",
    influenceChartImage = "",
    topUsersChartImage = "",
  } = req.body;

  res.setHeader("Content-Type", "application/pdf");
  res.setHeader(
    "Content-Disposition",
    `attachment; filename=vyft-program-report-${label}-${period}.pdf`
  );

  const doc = new PDFDocument({ size: "A4", margin: 32 });

  doc.pipe(res);

  // --- PAGE 1 : Titre, entreprise, période, grille influence ---
  doc.rect(0, 0, doc.page.width, doc.page.height).fill("#DBDFE0");
  doc.image("public/Vyft_program.png", doc.page.width / 2 - 90, 32, { width: 180, height: 80 });
  doc.moveDown(3);
  doc.fillColor("#1a7f6b").fontSize(28).font("Helvetica-Bold").text(`Rapport ${label}`, { align: "center" });
  doc.moveDown(0.5);
  doc.fontSize(18).font("Helvetica-Bold").text(companyName || "Vyft", { align: "center" });
  doc.moveDown(0.5);
  doc.fontSize(14).fillColor("#222").font("Helvetica").text(`Période : ${period}`, { align: "center" });
  doc.moveDown(1);

  doc.roundedRect(32, doc.y, doc.page.width - 64, 120, 18).fill("#fff");
  doc.fillColor("#444444").fontSize(18).font("Helvetica-Bold").text("Influence & bénéfice estimé (800 derniers jours)", 48, doc.y - 110);
  doc.moveDown(0.5);

  // Légende influence
  doc.fontSize(10).fillColor("#222").text("Faible", 48, doc.y);
  let x = 90;
  themeColors.forEach((color) => {
    doc.rect(x, doc.y - 8, 18, 10).fill(color);
    x += 22;
  });
  doc.fontSize(10).fillColor("#222").text("Forte influence", x, doc.y - 2);

  // Grille influence simplifiée
  doc.moveDown(2);
  doc.fontSize(12).fillColor("#222").text("Grille influence (simplifiée) :");
  const gridData = Array(800)
    .fill(0)
    .map((_, i) => {
      const date = influenceHistory[i]?.date || "";
      const count = influenceHistory[i]?.count || 0;
      return { count, date };
    });
  const max = Math.max(...gridData.map((g) => g.count), 1);
  let gridX = 48;
  let gridY = doc.y;
  const nbCols = 32;
  const nbRows = 25;
  const cellSize = 10;
  for (let row = 0; row < nbRows; row++) {
    for (let col = 0; col < nbCols; col++) {
      const idx = row * nbCols + col;
      const cell = gridData[idx];
      doc.rect(gridX + col * cellSize, gridY + row * cellSize, cellSize - 1, cellSize - 1)
        .fill(getInfluenceColor(cell.count, max));
    }
  }
  doc.moveDown(3);

  doc.fontSize(16).fillColor("#222").font("Helvetica-Bold").text("Résumé des indicateurs :", { align: "left" });
  doc.fontSize(14).font("Helvetica").list([
    `Total des pas : ${data?.totalSteps ?? 0}`,
    `Distance totale : ${data?.totalDistance ?? 0} km`,
    `Revenu estimé : ${data?.totalRevenue ?? 0} €`,
    `Croissance : ${data?.growth ?? "0 %"}`,
  ]);
  doc.text(`Page 1 / 3`, doc.page.width / 2 - 30, doc.page.height - 40, { align: "center" });
  doc.addPage();

  // --- PAGE 2 : Graphiques (images non incluses, placeholder) ---
  doc.rect(0, 0, doc.page.width, doc.page.height).fill("#DBDFE0");
  doc.fontSize(22).fillColor("#1a7f6b").font("Helvetica-Bold").text("Profit de marché", { align: "center" });
  doc.moveDown();
  doc.roundedRect(32, doc.y, doc.page.width - 64, 120, 18).fill("#fff");
  doc.fontSize(14).fillColor("#222").font("Helvetica").text("Graphique non inclus dans ce PDF (API Next.js, pas d'image).", 48, doc.y - 110);
  doc.moveDown(2);

  doc.fontSize(22).fillColor("#1a7f6b").font("Helvetica-Bold").text("Influence", { align: "center" });
  doc.moveDown();
  doc.roundedRect(32, doc.y, doc.page.width - 64, 120, 18).fill("#fff");
  doc.fontSize(14).fillColor("#222").font("Helvetica").text("Graphique non inclus dans ce PDF (API Next.js, pas d'image).", 48, doc.y - 110);

  doc.text(`Page 2 / 3`, doc.page.width / 2 - 30, doc.page.height - 40, { align: "center" });
  doc.addPage();

  // --- PAGE 3 : Top clients ---
  doc.rect(0, 0, doc.page.width, doc.page.height).fill("#DBDFE0");
  doc.fontSize(22).fillColor("#1a7f6b").font("Helvetica-Bold").text("Clients fréquents", { align: "center" });
  doc.moveDown();
  doc.roundedRect(32, doc.y, doc.page.width - 64, 220, 18).fill("#fff");
  doc.fontSize(14).fillColor("#222").font("Helvetica").text("Graphique non inclus dans ce PDF (API Next.js, pas d'image).", 48, doc.y - 210);
  doc.moveDown(2);
  doc.fontSize(14).fillColor("#222").font("Helvetica").text("Pour plus de détails, consultez l'application Vyft.", { align: "center" });

  doc.text(`Page 3 / 3`, doc.page.width / 2 - 30, doc.page.height - 40, { align: "center" });

  doc.end();
}